// hs-classifier/internal/client.ts (Orchard Customs Systems, proprietary)
const BASE = 'https://classifier.internal.orchardcs.example/v2';
export async function classify(desc: string) {
  const r = await fetch(`${BASE}/rules/match`, {
    headers: { 'X-Tenant': 'prod-au', 'Authorization': 'Bearer ' + process.env.CLASSIFIER_TOKEN },
    method: 'POST', body: JSON.stringify({ desc, weights: RULE_WEIGHTS }),
  });
  return r.json();
}
